// Highlight each project independently as its border charges.
const vertices=shapes.map(s=>s.split(' ').map(v=>v.split(',').map(Number)));
const charges=[...document.querySelectorAll('.moving-earth-piece')].map((g,i)=>{
 const points=vertices[i],a=points[0],d='M '+points.map(v=>v.join(' ')).join(' L ')+' Z';
 const layer=document.createElementNS('http://www.w3.org/2000/svg','g');layer.setAttribute('class','panel-charge');
 layer.innerHTML=`<clipPath id="charge-area-${i}"><circle cx="${a[0]}" cy="${a[1]}" r="0"/></clipPath><polygon class="charge-fill" points="${shapes[i]}" clip-path="url(#charge-area-${i})"/><path class="charge-outline" d="${d}" pathLength="1"/><circle class="charge-front" r="5"/>${points.map((v,k)=>`<circle class="charge-star" cx="${v[0]}" cy="${v[1]}" r="3" style="animation-delay:${-k*.37}s"/>`).join('')}`;
 g.insertBefore(layer,g.querySelector('.piece-label'));return {g,layer,path:layer.querySelector('.charge-outline'),radius:Math.max(...points.map(v=>Math.hypot(v[0]-a[0],v[1]-a[1])))};
});
function updateCharges(p,paused){charges.forEach(({g,layer,path,radius},i)=>{
 const t=limit((p-(.2+i*.1))/.075),amount=paused?(t>=1?1:0):t;
 layer.style.opacity=amount>0?1:0;layer.classList.toggle('charged',amount>=1);layer.classList.toggle('quiet',paused);
 path.style.strokeDasharray='1';path.style.strokeDashoffset=1-amount;
 layer.querySelector('clipPath circle').setAttribute('r',radius*amount);
 const point=path.getPointAtLength(path.getTotalLength()*amount),front=layer.querySelector('.charge-front');front.setAttribute('cx',point.x);front.setAttribute('cy',point.y);front.style.opacity=amount>0&&amount<1?1:0;
 g.classList.toggle('fully-charged',amount>=1);
 });}
let active=-1;const limit=v=>Math.max(0,Math.min(1,v)),smooth=v=>{v=limit(v);return v*v*v*(v*(v*6-15)+10)};let needsFrame=true;
function projectProgress(){return limit(((window.cinematicY??scrollY)-section.offsetTop)/(section.offsetHeight-innerHeight))}
function update(){const p=projectProgress(),paused=document.querySelector('#motion').getAttribute('aria-pressed')==='true',spread=paused?1:smooth((p-.12)/.08),reveal=smooth((p-.17)/.03),exit=0;const index=Math.min(6,Math.max(0,Math.floor((p-.2)/.1)));
 updateCharges(p,paused);
 const visible=p>=.2&&p<.97;document.querySelector('.movie-project').style.opacity=visible?1:0;document.querySelector('.movie-project').inert=!visible;
 const entrance=smooth(((window.cinematicY??scrollY)-(section.offsetTop-innerHeight*.9))/(innerHeight*1.05));
 const stage=document.querySelector('.project-movie-stage');
 stage.style.opacity=entrance*(1-smooth((((window.cinematicY??scrollY)-(section.offsetTop+(section.offsetHeight-innerHeight)*.9))/innerHeight-.15)/1.6));stage.style.transform=paused?'none':`scale(${1.045-.045*entrance})`;stage.style.filter=paused?'none':`blur(${(1-entrance)*3}px)`;
 stage.style.visibility=entrance>0?'visible':'hidden';
 stage.style.pointerEvents=entrance>0.95?'auto':'none';
 document.querySelector('.movie-title').style.opacity=smooth((p-.035)/.025)*(1-smooth((p-.115)/.04));
 const framing=paused?1:smooth((p-.12)/.08);
 const view=[-120+( -190+120)*framing,260+80*framing,1264+140*framing,1080-250*framing];
 document.querySelector('#spreading-earth').setAttribute('viewBox',view.join(' '));
 document.querySelector('.assembled-earth').style.opacity=1-spread*.91;
 const svg=document.querySelector('#spreading-earth');svg.style.height=(innerWidth<761?72-19*framing:100-32*framing)+'%';svg.style.top=(innerWidth<761?9+6*framing:7*framing)+'%';svg.style.transform=`scale(${(1+ .08*smooth(p/.06)-.08*smooth((p-.09)/.03))*(1-exit*.2)})`;svg.style.opacity=1-exit*.75;
 document.querySelectorAll('.moving-earth-piece').forEach((g,i)=>{const [dx,dy,r]=motion[i],c=centers[i],pieceSpread=paused?1:smooth((p-.12-i*.002)/.085);g.setAttribute('transform',`translate(${dx*pieceSpread} ${dy*pieceSpread}) rotate(${r*pieceSpread} ${c[0]} ${c[1]})`);g.classList.toggle('current',visible&&i===index);g.querySelector('.piece-label').style.opacity=reveal;g.style.opacity=visible&&i!==index?(g.classList.contains('fully-charged')?.85:.48):1;});
 if(active!==index){active=index;const item=projects[index];document.querySelector('#movie-category').textContent=item.category;document.querySelector('#movie-project-title').textContent=item.title;document.querySelector('#movie-summary').textContent=item.summary;document.querySelector('#movie-body').textContent=item.body;document.querySelector('#movie-repo').href='https://github.com/DeV-PrasiddhA/'+item.repo;}
 document.querySelector('#movie-count').textContent=p<.2?'EARTH / UNFOLDING':`0${index+1} / 07`;
 document.querySelector('#movie-next').textContent=p<.2?'Keep scrolling to reveal ↓':index<6?'Next project ↓':'Continue the journey ↓';document.querySelector('#movie-pause').textContent=paused?'Resume motion':'Pause motion';document.querySelector('.movie-progress i').style.width=p*100+'%';needsFrame=false;
}
let lastSceneY=-1;function tick(){const y=window.cinematicY??scrollY;if(needsFrame||Math.abs(y-lastSceneY)>.01){update();lastSceneY=y;}requestAnimationFrame(tick)}requestAnimationFrame(tick);addEventListener('scroll',()=>needsFrame=true,{passive:true});addEventListener('resize',()=>needsFrame=true);
new MutationObserver(()=>needsFrame=true).observe(document.querySelector('#motion'),{attributes:true,attributeFilter:['aria-pressed']});document.querySelector('#movie-pause').onclick=()=>document.querySelector('#motion').click();
document.querySelector('#movie-next').onclick=()=>{const p=projectProgress(),target=p<.2?.215:active<6?.215+(active+1)*.1:1;scrollTo({top:section.offsetTop+target*(section.offsetHeight-innerHeight),behavior:document.querySelector('#motion').getAttribute('aria-pressed')==='true'?'instant':'smooth'})};

